class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> result = new ArrayList<>();
        int patternLength = p.length();
        if (s.length() < patternLength) {
            return result;
        }

        int[] patternCount = new int[26];
        int[] windowCount = new int[26];
        for (char ch : p.toCharArray()) {
            patternCount[ch - 'a']++;
        }

        int matches = 0;
        for (int i = 0; i < 26; i++) {
            if (patternCount[i] == 0) {
                matches++;
            }
        }

        for (int right = 0; right < s.length(); right++) {
            int in = s.charAt(right) - 'a';
            windowCount[in]++;
            if (windowCount[in] == patternCount[in]) {
                matches++;
            } else if (windowCount[in] == patternCount[in] + 1) {
                matches--;
            }

            if (right >= patternLength) {
                int out = s.charAt(right - patternLength) - 'a';
                windowCount[out]--;
                if (windowCount[out] == patternCount[out]) {
                    matches++;
                } else if (windowCount[out] == patternCount[out] - 1) {
                    matches--;
                }
            }

            if (right >= patternLength - 1 && matches == 26) {
                result.add(right - patternLength + 1);
            }
        }

        return result;
    }
}

