class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> result = new ArrayList<>();
        int patternLength = p.length();
        if (s.length() < patternLength) {
            return result;
        }

        int[] need = new int[26];
        for (char ch : p.toCharArray()) {
            need[ch - 'a']++;
        }

        int missing = patternLength;
        for (int right = 0; right < s.length(); right++) {
            int in = s.charAt(right) - 'a';
            if (need[in] > 0) {
                missing--;
            }
            need[in]--;

            if (right >= patternLength) {
                int out = s.charAt(right - patternLength) - 'a';
                need[out]++;
                if (need[out] > 0) {
                    missing++;
                }
            }

            if (right >= patternLength - 1 && missing == 0) {
                result.add(right - patternLength + 1);
            }
        }

        return result;
    }
}

import java.util.*;

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> result = new ArrayList<>();
        int patternLength = p.length();
        if (s.length() < patternLength) {
            return result;
        }

        char[] sortedPattern = p.toCharArray();
        Arrays.sort(sortedPattern);

        for (int start = 0; start + patternLength <= s.length(); start++) {
            char[] window = s.substring(start, start + patternLength).toCharArray();
            Arrays.sort(window);
            if (Arrays.equals(sortedPattern, window)) {
                result.add(start);
            }
        }

        return result;
    }
}
